package com.loyu3c.rental;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import javax.xml.parsers.DocumentBuilderFactory;import org.junit.Test;import static org.junit.Assert.*;
public class OwnerWorkbookTest {
    private JSONObject row()throws Exception{return new JSONObject().put("id","p").put("name","A棟").put("billed",9760).put("paid",9760).put("remaining",0).put("cash",23050).put("topups",0).put("expenses",30000).put("held",20000).put("net",-6950);}
    private Map<String,String> workbook()throws Exception{JSONObject r=row();JSONObject tenant=new JSONObject(r.toString()).put("propertyId","p").put("code","001").put("name","=SUM(1,2) <王&小明>\u0001").put("status","本月帳單已清");JSONObject report=new JSONObject().put("month","2026-10").put("total",r).put("properties",new JSONArray().put(r)).put("tenants",new JSONArray().put(tenant));ByteArrayOutputStream out=new ByteArrayOutputStream();OwnerWorkbook.write(out,report);Map<String,String> entries=new HashMap<>();try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(out.toByteArray()))){ZipEntry e;while((e=z.getNextEntry())!=null){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] bytes=new byte[1024];int n;while((n=z.read(bytes))!=-1)b.write(bytes,0,n);String xml=b.toString(StandardCharsets.UTF_8.name());DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new ByteArrayInputStream(b.toByteArray()));entries.put(e.getName(),xml);}}return entries;}
    @Test public void amountsAreNumericWithCommaFormatIncludingNegative()throws Exception{Map<String,String> w=workbook();assertTrue(w.get("xl/styles.xml").contains("formatCode=\"#,##0;[Red]-#,##0\""));assertTrue(w.get("xl/worksheets/sheet2.xml").contains("<c r=\"B2\" s=\"2\"><v>9760</v></c>"));assertTrue(w.get("xl/worksheets/sheet2.xml").contains("<v>-6950</v>"));assertFalse(w.get("xl/worksheets/sheet2.xml").contains("9,760"));}
    @Test public void separateSheetsFreezeFilterAndTreatTenantCodesAsText()throws Exception{Map<String,String> w=workbook();assertEquals(8,w.size());assertTrue(w.get("xl/workbook.xml").contains("租約明細"));String s=w.get("xl/worksheets/sheet3.xml");assertTrue(s.contains("state=\"frozen\""));assertTrue(s.contains("<autoFilter ref=\"A1:J2\""));assertTrue(s.contains("<c r=\"B2\" s=\"0\" t=\"inlineStr\""));assertTrue(s.contains(">001</t>"));}
    @Test public void namesAreEscapedInlineTextAndNeverFormulas()throws Exception{Map<String,String> w=workbook();String s=w.get("xl/worksheets/sheet3.xml");assertTrue(s.contains("=SUM(1,2) &lt;王&amp;小明&gt;"));assertFalse(s.contains("<f>"));assertFalse(s.contains("\u0001"));}
}
